#pragma once
#include <juce_audio_utils/juce_audio_utils.h>
#include <array>
namespace cortex::presets {
constexpr int maximumBytes=256*1024;
enum Kind{number,boolean,choice,projection,root,voices,integer};
struct Field{const char* group;const char* key;const char* id;Kind kind;double low,high;};
inline const std::array<Field,33> fields{{
 {"engine","mode","network",choice,0,2},{"engine","coupling","coupling",number,0,8},{"engine","noise","noise",number,0,2},{"engine","drift","drift",number,0,2},{"engine","projection","projection",projection,-1,1},{"engine","pulseMode","pulsemode",choice,0,2},{"engine","pulseEnabled","pulses",boolean,0,1},{"engine","pulseRate","rate",number,.25,12},{"engine","pulseJitter","jitter",number,0,1},{"engine","pulseStrength","strength",number,0,1},{"engine","attack","attack",number,.03,2},{"engine","decay","decay",number,.03,4},{"engine","sustain","sustain",number,0,1},{"engine","release","release",number,.03,5},
 {"audio","tuningMode","tuning",choice,0,1},{"audio","root","root",root,32.703,1046.503},{"audio","scale","scale",choice,0,2},{"audio","detune","detune",number,0,100},{"audio","tone","tone",number,0,1},{"audio","space","space",number,0,1},{"audio","output","output",number,0,1},{"audio","reverb","reverb",number,0,1},{"audio","reverbSize","reverbSize",number,0,1},{"audio","spread","spread",number,0,1},{"audio","variation","variation",number,0,1},{"audio","octaves","octaves",integer,0,3},{"audio","voiceLimit","voices",voices,4,16},{"audio","binaural","binaural",boolean,0,1},{"audio","droneEnabled","play",boolean,0,1},{"audio","difference","difference",number,2,50},{"audio","orbitEnabled","orbitEnabled",boolean,0,1},{"audio","orbitRate","orbitRate",number,.01,.5},{"audio","orbitDepth","orbitDepth",number,0,1}
}};
inline juce::StringArray names(const Field& f){if(juce::String(f.id)=="network")return {"islands","global","modular"};if(juce::String(f.id)=="pulsemode")return {"regional","brainstorm","rain"};if(juce::String(f.id)=="tuning")return {"locked","free"};return {"minor","major","fifths"};}
inline bool numeric(const juce::var& v){return v.isInt()||v.isInt64()||v.isDouble();}
struct Patch{juce::String name;std::array<float,33> values{};};
inline bool decode(const juce::String& text,Patch& patch,juce::String& error){
 auto fail=[&](const juce::String& message){error=message;return false;};if(text.getNumBytesAsUTF8()>maximumBytes)return fail("Preset exceeds 256 KiB.");juce::var doc;auto parsed=juce::JSON::parse(text,doc);if(parsed.failed()||doc.getDynamicObject()==nullptr)return fail("Invalid preset JSON.");auto* object=doc.getDynamicObject();
 // Complete canonical factory files predate the envelope marker; explicit wrong markers reject.
 if(object->hasProperty("format")&&(!doc["format"].isString()||doc["format"].toString()!="cortex65-preset"))return fail("Unsupported preset format.");if(!numeric(doc["version"])||double(doc["version"])!=1)return fail("Unsupported preset version.");if(!doc["name"].isString())return fail("Preset name must be text.");patch.name=doc["name"].toString().trim();if(patch.name.isEmpty()||patch.name.length()>80)return fail("Preset name must contain 1–80 characters.");if(doc["engine"].getDynamicObject()==nullptr||doc["audio"].getDynamicObject()==nullptr)return fail("Missing engine or audio settings.");
 int orbitFields=0;for(auto key:{"orbitEnabled","orbitRate","orbitDepth"})orbitFields+=doc["audio"].getDynamicObject()->hasProperty(key)?1:0;if(orbitFields!=0&&orbitFields!=3)return fail("Head Orbit settings must include all three fields.");
 for(size_t i=0;i<fields.size();++i){if(i>=30&&orbitFields==0){patch.values[i]=i==30?0:i==31?.07f:.7f;continue;}const auto& f=fields[i];const auto value=doc[f.group][f.key];double n=0;if(f.kind==boolean){if(!value.isBool())return fail(juce::String(f.key)+" must be true or false.");n=bool(value)?1:0;}else if(f.kind==choice){if(!value.isString())return fail(juce::String(f.key)+" must be a named choice.");n=names(f).indexOf(value.toString());if(n<0)return fail(juce::String(f.key)+" is not a supported choice.");}else{if(!numeric(value)||!std::isfinite(double(value)))return fail(juce::String(f.key)+" must be a finite number.");n=double(value);double tolerance=1e-9*std::max(1.,f.high-f.low);if(n<f.low-tolerance||n>f.high+tolerance)return fail(juce::String(f.key)+" is out of range.");n=juce::jlimit(f.low,f.high,n);if((f.kind==integer||f.kind==projection||f.kind==voices)&&std::abs(n-std::round(n))>1e-9)return fail(juce::String(f.key)+" must be an integer.");if(f.kind==projection)n=n<0?2:n;if(f.kind==root)n=juce::jlimit(24,84,int(std::round(69+12*std::log2(n/440))));if(f.kind==voices){if(n!=4&&n!=8&&n!=16)return fail("Voice limit must be 4, 8 or 16.");n=n==4?0:n==8?1:2;}}patch.values[i]=float(n);}
 if(patch.values[30]>.5f)patch.values[27]=0; // Orbit takes precedence over beat-pair routing.
 error.clear();return true;
}
inline juce::String encode(const juce::AudioProcessorValueTreeState& state,juce::String name){name=name.trim();if(name.isEmpty()||name.length()>80)return {};juce::var doc(new juce::DynamicObject),engine(new juce::DynamicObject),audio(new juce::DynamicObject);auto* object=doc.getDynamicObject();object->setProperty("format","cortex65-preset");object->setProperty("version",1);object->setProperty("name",name);
 for(const auto& f:fields){double n=state.getRawParameterValue(f.id)->load();juce::var value;if(f.kind==boolean)value=juce::String(f.id)=="binaural"&&state.getRawParameterValue("orbitEnabled")->load()>.5f?false:n>.5;else if(f.kind==choice)value=names(f)[int(n)];else{if(f.kind==root)n=juce::MidiMessage::getMidiNoteInHertz(int(n));if(f.kind==projection)n=n==2?-1:n;if(f.kind==voices)n=4<<int(n);value=juce::jlimit(f.low,f.high,n);}auto* group=juce::String(f.group)=="engine"?engine.getDynamicObject():audio.getDynamicObject();group->setProperty(f.key,value);}object->setProperty("engine",engine);object->setProperty("audio",audio);return juce::JSON::toString(doc,true);
}
}
